-- Demo-only schema. Do not use permissive policies for private production conversations.
create table if not exists public.messages(id bigint generated by default as identity primary key,room_id text not null,sender text not null,body text not null,kind text not null default 'text',created_at timestamptz not null default now());
create index if not exists messages_room_created_idx on public.messages(room_id,created_at);
alter table public.messages enable row level security;
create policy "demo read messages" on public.messages for select to anon,authenticated using(true);
create policy "demo insert messages" on public.messages for insert to anon,authenticated with check(true);
create table if not exists public.call_signals(id bigint generated by default as identity primary key,room_id text not null,sender text not null,payload jsonb not null,created_at timestamptz not null default now());
alter table public.call_signals enable row level security;
create policy "demo read call signals" on public.call_signals for select to anon,authenticated using(true);
create policy "demo insert call signals" on public.call_signals for insert to anon,authenticated with check(true);
-- Enable Realtime for messages and call_signals in Database > Publications.
-- Create a Storage bucket named chat-media. Public bucket is demo-only; use private storage and signed URLs in production.
